violation.text:
PREFIX sdlc: <https://decision-driven-design.dk/ns/sdlc#>
SELECT ?subject ?reason WHERE {
  {
    VALUES (?fromLayer ?fromRank) { ("domain" 1) ("application" 2) ("infrastructure" 3) ("host" 4) ("test" 5) }
    VALUES (?toLayer ?toRank) { ("domain" 1) ("application" 2) ("infrastructure" 3) ("host" 4) ("test" 5) }
    ?subject a sdlc:Component ; sdlc:inTarget ?target ; sdlc:ofSystem ?system ;
             sdlc:inLayer ?fromLayer ; sdlc:dependsOn ?to .
    ?system sdlc:within* ?anchor .
    ?to sdlc:inLayer ?toLayer .
    FILTER (?fromRank < ?toRank)
    BIND (CONCAT("depends on a higher layer: ", STR(?to)) AS ?reason)
  } UNION {
    ?subject a sdlc:Component ; sdlc:inTarget ?target ; sdlc:ofSystem ?system .
    ?system sdlc:within* ?anchor .
    FILTER NOT EXISTS { ?subject sdlc:inLayer ?l . FILTER (?l IN ("domain", "application", "infrastructure", "host", "test")) }
    BIND ("in no layer this decision declares" AS ?reason)
  }
}
